// Les imports viennent de org.junit.jupiter : c'est JUnit 5.
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

// La classe à tester : une simple calculatrice.
class Calculatrice {
    int additionner(int a, int b) {
        return a + b;
    }
}

// Une classe de test : par convention, on la nomme <ClasseTestee>Test.
class CalculatriceTest {

    // @Test marque cette méthode comme un test que JUnit doit lancer.
    @Test
    void additionner_deuxNombres_renvoieLaSomme() {
        Calculatrice calc = new Calculatrice();
        int resultat = calc.additionner(2, 3);
        // On vérifie que le résultat vaut bien 5.
        assertEquals(5, resultat);
    }
}

