import org.junit.jupiter.api.Test;
// On importe les assertions en static pour les appeler sans préfixe.
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assertions.assertFalse;

class AssertionsDemoTest {

    @Test
    void exemples() {
        // assertEquals(attendu, obtenu) : vérifie l'égalité. L'attendu vient TOUJOURS en premier.
        assertEquals(5, 2 + 3);

        // assertTrue(condition) : vérifie qu'une condition est vraie.
        assertTrue(10 > 3);

        // assertFalse(condition) : vérifie qu'une condition est fausse.
        assertFalse("".length() > 0);
    }
}

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertEquals;

class DivisionTest {

    int diviser(int a, int b) {
        if (b == 0) {
            throw new IllegalArgumentException("division par zero interdite");
        }
        return a / b;
    }

    @Test
    void diviser_parZero_leveUneException() {
        // assertThrows(TypeAttendu.class, () -> codeQuiDoitEchouer)
        // Le code à tester est passé sous forme de lambda () -> ...
        IllegalArgumentException ex = assertThrows(
            IllegalArgumentException.class,
            () -> diviser(10, 0)
        );
        // Bonus : on peut vérifier le message de l'exception.
        assertEquals("division par zero interdite", ex.getMessage());
    }
}

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

record Point(int x, int y) { }

class Geometrie {
    // Déplace un point d'un certain décalage et renvoie un NOUVEAU point.
    Point deplacer(Point p, int dx, int dy) {
        return new Point(p.x() + dx, p.y() + dy);
    }
}

class GeometrieTest {

    @Test
    void deplacer_ajouteLeDecalage() {
        Geometrie g = new Geometrie();
        Point obtenu = g.deplacer(new Point(1, 1), 2, 3);
        // Grâce à l'égalité par valeur des records, une seule assertion suffit.
        assertEquals(new Point(3, 4), obtenu);
    }
}

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

// Une petite hiérarchie fermée de formes.
sealed interface Forme permits Cercle, Carre { }
record Cercle(double rayon) implements Forme { }
record Carre(double cote) implements Forme { }

class CalculAire {
    // Le switch branche selon le TYPE et déconstruit le record au passage.
    double aire(Forme f) {
        return switch (f) {
            case Cercle(double r) -> Math.PI * r * r;
            case Carre(double c)  -> c * c;
        };
    }
}

class CalculAireTest {

    @Test
    void aire_duCarre() {
        assertEquals(9.0, new CalculAire().aire(new Carre(3)));
    }

    @Test
    void aire_duCercle() {
        // Pour des nombres à virgule, on tolère un petit écart (delta).
        assertEquals(Math.PI, new CalculAire().aire(new Cercle(1)), 0.0001);
    }
}

