import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.DisplayName;
import static org.junit.jupiter.api.Assertions.assertEquals;

class Panier {
    private int total = 0;
    void ajouter(int prix) { total += prix; }
    int total() { return total; }
}

@DisplayName("Le panier d'achat")
class PanierTest {

    private Panier panier;

    // Exécuté avant CHAQUE test : chaque test part d'un panier neuf et vide.
    @BeforeEach
    void preparer() {
        panier = new Panier();
    }

    @Test
    @DisplayName("commence vide avec un total de 0")
    void panierNeuf_totalZero() {
        assertEquals(0, panier.total());
    }

    @Test
    @DisplayName("additionne le prix des articles ajoutés")
    void ajouter_deuxArticles_cumuleLesPrix() {
        panier.ajouter(10); // arrange + act
        panier.ajouter(5);
        assertEquals(15, panier.total()); // assert
    }
}
